ListNode* detectCycle(ListNode* head) {
    ListNode *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {                  // phase 1: find ANY meeting point
            ListNode* p = head;              // phase 2: reset one to the head
            while (p != slow) { p = p->next; slow = slow->next; }   // 1 step each
            return p;                        // they meet AT the cycle entry
        }
    }
    return nullptr;
}

ListNode* reverseFrom(ListNode* head) {
    ListNode *prev = nullptr, *cur = head;
    while (cur) { ListNode* ahead = cur->next; cur->next = prev; prev = cur; cur = ahead; }
    return prev;
}

bool isPalindrome(ListNode* head) {
    if (!head || !head->next) return true;
    ListNode *slow = head, *fast = head;
    while (fast->next && fast->next->next) {   // FIRST middle: tail starts after slow
        slow = slow->next;
        fast = fast->next->next;
    }
    ListNode* second = reverseFrom(slow->next);

    bool ok = true;
    for (ListNode *a = head, *b = second; b; a = a->next, b = b->next)
        if (a->val != b->val) { ok = false; break; }

    slow->next = reverseFrom(second);           // RESTORE: leave the caller's list intact
    return ok;
}

ListNode* removeNthFromEnd(ListNode* head, int n) {
    ListNode dummy(0); dummy.next = head;      // dummy handles "remove the head"
    ListNode *front = &dummy, *back = &dummy;
    for (int i = 0; i < n; ++i) front = front->next;   // open the gap
    while (front->next) { front = front->next; back = back->next; }
    ListNode* target = back->next;
    back->next = target->next;
    delete target;
    return dummy.next;
}

