def remove_nth_from_end(head, n: int):
    dummy = ListNode(0, head)          # dummy handles "remove the head"
    front = back = dummy
    for _ in range(n):
        front = front.next             # open the gap
    while front.next:
        front = front.next
        back = back.next
    back.next = back.next.next
    return dummy.next

