def merge_two_lists(a, b):
    dummy = ListNode()
    tail = dummy
    while a and b:
        if a.val <= b.val:          # <= keeps it stable
            tail.next, a = a, a.next
        else:
            tail.next, b = b, b.next
        tail = tail.next
    tail.next = a if a else b       # DRAIN: at most one list is non-empty
    return dummy.next


def merge_rec(a, b):
    """Recursive twin: pick the smaller head, let recursion merge the rest."""
    if a is None:
        return b
    if b is None:
        return a
    if a.val <= b.val:
        a.next = merge_rec(a.next, b)
        return a
    b.next = merge_rec(a, b.next)
    return b

