ListNode* getIntersectionNode(ListNode* a, ListNode* b) {
    if (!a || !b) return nullptr;
    ListNode *p = a, *q = b;
    while (p != q) {
        // each pointer walks its own list then the other: both cover m+n
        p = p ? p->next : b;
        q = q ? q->next : a;
    }
    return p;      // the intersection, or nullptr if both hit the end together
}

