def get_intersection_node(a, b):
    if a is None or b is None:
        return None
    p, q = a, b
    while p is not q:
        # each pointer walks its own list then the other: both cover m+n
        p = p.next if p else b
        q = q.next if q else a
    return p       # the intersection, or None if both hit the end together

