// Given ONLY the node to delete -- no head, no predecessor.
void deleteNode(ListNode* node) {
    node->val = node->next->val;      // impersonate the successor
    ListNode* doomed = node->next;
    node->next = doomed->next;        // then unlink the successor instead
    delete doomed;
}

ListNode* oddEvenList(ListNode* head) {
    if (!head || !head->next) return head;
    ListNode *odd = head, *even = head->next, *evenHead = even;
    while (even && even->next) {
        odd->next = even->next;     // odd takes the node after even
        odd = odd->next;
        even->next = odd->next;     // even takes the node after that
        even = even->next;
    }
    odd->next = evenHead;           // stitch the even chain onto the odd tail
    return head;
}

ListNode* deleteMiddle(ListNode* head) {
    if (!head || !head->next) { delete head; return nullptr; }   // 1 node -> empty
    ListNode *slow = head, *fast = head, *prev = nullptr;
    while (fast && fast->next) {
        prev = slow;                 // trail by assigning BEFORE slow advances
        slow = slow->next;
        fast = fast->next->next;
    }
    prev->next = slow->next;
    delete slow;
    return head;
}
